with valid as (select *, cast(amount as int) as amount_int from orders where channel = 'mobile') select status, count(*) filter (where channel = 'web') as web_rows, count_if(channel = 'store') as store_events, count_if(status = 'CANCELLED') as cancelled_events, percentile_approx(amount_int, array(0.25, 0.5, 0.75)) as amount_int_quartiles, count(*) filter (where channel = 'mobile') as mobile_rows from valid group by 1 order by web_rows desc nulls last;
